std::vector<Point2d> result;
const double EPS = 1e-8;

auto det = [](double a, double b, double c, double d) { return a * d - b * c; };

auto onSegment = [](const Point2d& a, const Point2d& b, const Point2d& p) {
    if (std::min(a.x, b.x) - EPS <= p.x && p.x <= std::max(a.x, b.x) + EPS &&
        std::min(a.y, b.y) - EPS <= p.y && p.y <= std::max(a.y, b.y) + EPS) {
        return true;
    }
    return false;
};

for (size_t i = 0; i < segments.size(); ++i) {
    const Segment2d& s1 = segments[i];
    for (size_t j = i + 1; j < segments.size(); ++j) {
        const Segment2d& s2 = segments[j];

        double x1 = s1.p1.x, y1 = s1.p1.y;
        double x2 = s1.p2.x, y2 = s1.p2.y;
        double x3 = s2.p1.x, y3 = s2.p1.y;
        double x4 = s2.p2.x, y4 = s2.p2.y;

        double denom = det(x1 - x2, y1 - y2, x3 - x4, y3 - y4);
        double numX = det(x1 * y2 - y1 * x2, x1 - x2, x3 * y4 - y3 * x4, x3 - x4);
        double numY = det(x1 * y2 - y1 * x2, y1 - y2, x3 * y4 - y3 * x4, y3 - y4);

        if (std::abs(denom) < EPS) {
            // Collinear or parallel
            continue;
        }

        double x = numX / denom;
        double y = numY / denom;

        Point2d p{x, y};

        if (onSegment(s1.p1, s1.p2, p) && onSegment(s2.p1, s2.p2, p)) {
            bool duplicate = false;
            for (const Point2d& pt : result) {
                if (std::abs(pt.x - p.x) < EPS && std::abs(pt.y - p.y) < EPS) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) {
                result.push_back(p);
            }
        }
    }
}

return result;
// END_CODE

